+    const url = new URL(route.request().url());
+    let body: unknown = [];
+    if (url.pathname === '/api/auth/status') body = admin;
+    if (url.pathname === '/api/users') body = [{ ...admin, workgroups: [group, { id: 43, name: 'Another team' }] }];
+    if (url.pathname === '/api/workgroups') body = [group];
+    if (url.pathname === '/api/workgroups/42') body = group;
+    if (!empty) {
+      if (url.pathname === '/api/workgroups/42/users') body = [{ id: 2, username: 'member', email: 'member@example.com' }];
+      if (url.pathname === '/api/workgroups/42/assets') body = [{ id: 3, name: 'app-server', type: 'SERVER', ip: '192.0.2.10', owner: 'Example owner' }];
